create temporary table tc_csi_qa(result jsonb);
do $$
declare co uuid:=gen_random_uuid();otherco uuid:=gen_random_uuid();p uuid:=gen_random_uuid();otherp uuid:=gen_random_uuid();admin_ uuid:=gen_random_uuid();pm uuid:=gen_random_uuid();owner_ uuid:=gen_random_uuid();outsider uuid:=gen_random_uuid();request_ uuid:=gen_random_uuid();line_ jsonb;row_ jsonb;doc jsonb;catalog_ jsonb;batch uuid;account_ uuid;charge_ uuid;source_ text;checks integer:=0;c integer;denied boolean;
begin
 begin
 insert into auth.users(id,email) select x,x::text||'@qa.invalid' from unnest(array[admin_,pm,owner_,outsider]) x;
 insert into public.profiles(id,role,active) values(admin_,'admin',true),(pm,'pm',true),(owner_,'owner',true),(outsider,'admin',true) on conflict(id) do update set role=excluded.role,active=true;
 insert into public.companies(id,name) values(co,'Transient CSI QA'),(otherco,'Other transient CSI QA');
 insert into public.projects(id,company_id,name) values(p,co,'CSI QA Project'),(otherp,otherco,'Other CSI QA Project');
 insert into public.company_users(company_id,user_id,active) values(co,admin_,true),(otherco,outsider,true);
 insert into public.company_members(company_id,user_id,role) values(co,admin_,'admin'),(otherco,outsider,'admin');
 insert into public.project_members(project_id,user_id,role,active) values(p,pm,'pm',true),(p,owner_,'owner',true);
 perform set_config('request.jwt.claim.sub',admin_::text,true);execute 'set local role authenticated';
 catalog_:=public.tc_cost_catalog(co);if jsonb_array_length(catalog_->'codes')<>2724 then raise exception 'Reference count incorrect';end if;checks:=checks+1;
 row_:=public.tc_cost_add(co,'QA-SPECIAL','Special testing','OTHER');row_:=public.tc_cost_add(co,'QA-SPECIAL','Special testing','OTHER');
 catalog_:=public.tc_cost_catalog(co);if jsonb_array_length(catalog_->'codes')<>2725 then raise exception 'Custom retry duplicate';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_cost_add(co,'01200500','Overwrite reference','SUB');exception when unique_violation then denied:=true;end;if not denied then raise exception 'Reference overwritten';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',pm::text,true);catalog_:=public.tc_cost_catalog(co);if (catalog_->>'canManage')::boolean then raise exception 'PM gained catalog management';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_cost_add(co,'QA-NO','No access','SUB');exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'PM changed company catalog';end if;checks:=checks+1;
 line_:=public.tc_budget_add(p,request_,'{"code":"01200500","scope":"Office trailer","costType":"EQUIP","budget":"100.29"}');
 if line_->>'csi_code'<>'01200500' or (line_->>'forecast_cost')::numeric<>100.29 then raise exception 'Budget code/amount lost';end if;checks:=checks+1;
 row_:=public.tc_budget_add(p,request_,'{"code":"01200500","scope":"Office trailer","costType":"EQUIP","budget":"100.29"}');if row_->>'id'<>line_->>'id' then raise exception 'Budget retry duplicated';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_budget_add(p,gen_random_uuid(),'{"code":"NO-SUCH-CODE","scope":"No","costType":"SUB","budget":"5"}');exception when check_violation then denied:=true;end;if not denied then raise exception 'Unknown code accepted';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_budget_add(p,gen_random_uuid(),'{"code":"01200500","scope":"No","costType":"BAD","budget":"5"}');exception when check_violation then denied:=true;end;if not denied then raise exception 'Unknown type accepted';end if;checks:=checks+1;
 row_:=public.tc_budget_forecast((line_->>'id')::uuid,1,0);if (row_->>'forecast_cost')::numeric<>0 then raise exception 'Zero forecast lost';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_budget_forecast((line_->>'id')::uuid,1,200);exception when serialization_failure then denied:=true;end;if not denied then raise exception 'Stale budget edit accepted';end if;checks:=checks+1;
 denied:=false;begin update public.project_budget_lines set original_budget=1 where id=(line_->>'id')::uuid;exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Budget direct mutation accepted';end if;checks:=checks+1;
 execute 'set local role postgres';
 source_:=p::text||'/budgets/qa.csv';insert into storage.objects(bucket_id,name) values('project-documents',source_);
 doc:=public.tc_save_project_import(p,'budget',null,0,'qa.csv',source_,'{"proposedLines":[{"costCode":"03000000","description":"Concrete","originalBudget":50,"revisedBudget":50,"forecastCost":50,"committed":0,"actual":0}],"totalOriginal":50,"totalForecast":50}');
 doc:=public.tc_apply_project_import((doc->>'id')::uuid,1,'{}');
 row_:=public.tc_budget_forecast((line_->>'id')::uuid,2,100.29);
 if (select forecast_cost from public.projects where id=p)<>150.29 then raise exception 'Manual/import combined forecast wrong';end if;checks:=checks+1;
 doc:=public.tc_update_import_forecast((doc->>'id')::uuid,2,0,20);
 if (select forecast_cost from public.projects where id=p)<>120.29 then raise exception 'Import forecast dropped manual budget';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',owner_::text,true);execute 'set local role authenticated';
 select count(*) into c from public.project_budget_lines where project_id=p;if c<>0 then raise exception 'Owner sees private budget';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_cost_catalog(co);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Owner sees financial catalog';end if;checks:=checks+1;
 perform set_config('request.jwt.claim.sub',outsider::text,true);denied:=false;begin perform public.tc_budget_forecast((line_->>'id')::uuid,3,99);exception when insufficient_privilege then denied:=true;end;if not denied then raise exception 'Other company edited budget';end if;checks:=checks+1;
 select count(*) into c from public.tc_company_cost_codes where company_id=co;if c<>0 then raise exception 'Custom catalog leaked';end if;checks:=checks+1;
 execute 'set local role postgres';
 insert into public.tc_chart_of_accounts(company_id,account_code,account_name,account_type) values(co,'QA-CASH','Cash','asset'),(co,'QA-COGS','Job cost','cost_of_goods_sold');
 perform set_config('request.jwt.claim.sub',admin_::text,true);
 batch:=public.tc_create_journal_draft(co,'qa',null,current_date,'CSI typed journal',jsonb_build_array(jsonb_build_object('gl_account','QA-COGS','project_id',p,'csi_code','01200500','cost_type','EQUIP','scope_name','Trailer rental','debit',10),jsonb_build_object('gl_account','QA-CASH','credit',10)));
 if not exists(select 1 from public.tc_accounting_journal_lines where batch_id=batch and csi_code='01200500' and cost_type='EQUIP' and scope_name='Trailer rental') then raise exception 'Journal lost coding metadata';end if;checks:=checks+1;
 denied:=false;begin perform public.tc_create_journal_draft(co,'qa',null,current_date,'Invalid code',jsonb_build_array(jsonb_build_object('gl_account','QA-COGS','project_id',p,'csi_code','NONEXISTENT','debit',10),jsonb_build_object('gl_account','QA-CASH','credit',10)));exception when check_violation then denied:=true;end;if not denied then raise exception 'Accounting accepted unknown code';end if;checks:=checks+1;
 insert into public.tc_charge_accounts(company_id,account_name,account_type) values(co,'QA card','credit_card') returning id into account_;
 insert into public.tc_charge_transactions(account_id,transaction_date,amount,company_id) values(account_,current_date,10,co) returning id into charge_;
 row_:=public.tc_review_charge_split(charge_,jsonb_build_array(jsonb_build_object('project_id',p,'csi_code','01200500','cost_type','EQUIP','scope_name','Trailer charge scope','amount',10)));
 if not exists(select 1 from public.tc_charge_allocations where charge_id=charge_ and cost_type='EQUIP' and scope_name='Trailer charge scope') then raise exception 'Charge split lost type/scope';end if;checks:=checks+1;
 update public.tc_charge_transactions set classification_status='approved' where id=charge_;
 row_:=public.tc_prepare_charge_journal(charge_,'QA-COGS','QA-CASH');
 if not exists(select 1 from public.tc_accounting_journal_lines where batch_id=(row_->>'batch_id')::uuid and cost_type='EQUIP' and scope_name='Trailer charge scope') then raise exception 'Charge-to-journal lost coding';end if;checks:=checks+1;
 if not exists(select 1 from public.tc_budget_line_events where line_id=(line_->>'id')::uuid and action='forecast' and actor_id=pm) then raise exception 'Budget audit missing';end if;checks:=checks+1;
 raise exception using errcode='ZQ004',message='Rollback CSI fixtures';
 exception when sqlstate 'ZQ004' then null;
 end;
 if exists(select 1 from auth.users where id=admin_) then raise exception 'Fixtures persisted';end if;
 insert into tc_csi_qa values(jsonb_build_object('status','PASS','checks',checks,'fixtures_rolled_back',true));
end $$;
select result from tc_csi_qa;
